  (forall x, (x < lo \/ usp <= x) -> outside W x) -> kHighShadowEnd + 8 <= lo -> lo <= usp -> usp <= 2^47 -> 0 <= A ->
  pfmt_ok m' usp lo A VA t0 ds.
